    Edit('replace', 'A company\'s OWN sales totals - "total sales", "dealer sales", "project sales", "sales\nthis year", "compare sales 2025 vs 2026", "sales by month", "monthly sales", "jualan\ntahun ini", "销售总额" - with NO product code and NO customer named. It is a\nDIFFERENT ask from "sales report" above, which always names a product or a customer.\nA SALES ANALYSIS ask carries domain_hint "order", intent_hint "check_order" and\nentities [] (a channel word, a year or a company name is never an entity).\n  - "total project sales this year" -> order_status "sales_analysis", sales_channel\n    "project", group_by null\n  - "compare dealer sales 2025 vs 2026 by month" -> order_status "sales_analysis",\n    sales_channel "dealer", group_by "month", date_filter_start "2025-01-01",\n    date_filter_end "2026-12-31"\n  - "Mocha sales by month" -> order_status "sales_analysis", group_by "month",\n    sales_company "Mocha"\n  - "sales by year" -> order_status "sales_analysis", group_by "year"\nsales_channel is set on a sales analysis ask exactly as on a sales report ask\n("dealer" / "project", else null).', 'A company\'s OWN sales totals with NO product code and NO customer named ("total sales", "dealer sales", "project sales", "sales this year", "compare sales 2025 vs 2026", "sales by month", "monthly sales", "jualan tahun ini", "销售总额"); a "sales report" above always names a product or a customer. domain_hint "order", intent_hint "check_order", entities [] (a channel word, a year or a company name is never an entity); sales_channel as on a sales report ask ("dealer" / "project", else null).\n  - "compare dealer sales 2025 vs 2026 by month" -> order_status "sales_analysis", sales_channel "dealer", group_by "month", date_filter_start "2025-01-01", date_filter_end "2026-12-31"\n  - "Mocha sales by month" -> group_by "month", sales_company "Mocha"; "sales by year" -> group_by "year"'),
