    # lever 4: the box intro in the short form LOW STOCK REPORT FILTERS uses; keys unchanged.
    Edit('replace', 'Everything below is IN ADDITION to the OUTPUT object above. Emit these two keys on every\nobject, exactly as if they were listed there:', 'Two more OUTPUT keys, on every object:'),
    # lever 4: terse.
    Edit('replace', 'The axis the answer is BROKEN DOWN by: from the CURRENT message\'s own words only, any language, never inferred from context. Default null (a plain "list the outstanding DO" has no axis word -> null).', 'The axis the answer is BROKEN DOWN by, from the CURRENT message\'s own words only (any language), never inferred; default null ("list the outstanding DO" has no axis word).'),
    # compact formatting: six mapping rows on one line; every trigger and value kept.
    Edit('replace', '  - "by customer", "per customer", "customer by customer", "ikut pelanggan" -> "customer"\n  - "by transporter", "per transporter", "by lorry", "ikut lori" -> "transporter"\n  - "by date", "per day", "day by day", "ikut tarikh" -> "date"\n  - "by product", "per product", "by item", "ikut produk" -> "product"\n  - "per warehouse", "by warehouse", "by location", "ikut gudang" -> "warehouse"\n  - "by supplier", "per supplier", "ikut pembekal" -> "supplier"', '  - "by customer", "per customer", "customer by customer", "ikut pelanggan" -> "customer"; "by transporter", "per transporter", "by lorry", "ikut lori" -> "transporter"; "by date", "per day", "day by day", "ikut tarikh" -> "date"; "by product", "per product", "by item", "ikut produk" -> "product"; "per warehouse", "by warehouse", "by location", "ikut gudang" -> "warehouse"; "by supplier", "per supplier", "ikut pembekal" -> "supplier"'),
    # lever 4: terse; every trigger and value kept.
    Edit('replace', '"so_outstanding" = a SALES ORDER ordered but with NO delivery order yet; NOT "outstanding", which is a DO already created and not yet delivered.\n  - "SO outstanding", "outstanding SO", "outstanding sales order", "ordered but no DO", "no DO yet", "belum DO", "belum keluar DO", "还没出DO", "未出DO" -> "so_outstanding", under domain_hint "order" / intent_hint "check_order", NEVER purchase_order / check_po (check_po needs a PO or supplier word)\n  - "outstanding DO", "not delivered yet", "belum hantar" -> "outstanding" (unchanged)', '"so_outstanding" = a SALES ORDER ordered with NO delivery order yet; NOT "outstanding" (a DO already created, not yet delivered).\n  - "SO outstanding", "outstanding SO", "outstanding sales order", "ordered but no DO", "no DO yet", "belum DO", "belum keluar DO", "还没出DO", "未出DO" -> "so_outstanding", domain_hint "order" / intent_hint "check_order", NEVER purchase_order / check_po (that needs a PO or supplier word)\n  - "outstanding DO", "not delivered yet", "belum hantar" -> "outstanding" (unchanged)'),
    # class 1: "Order domain only, from the current message's explicit words" restates ORDER_STA
    Edit('replace', "The full set is now: outstanding|delivered|so_outstanding|do_outstanding|outstanding_both|null. Order domain only, from the current message's explicit words.", 'The full set is now: outstanding|delivered|so_outstanding|do_outstanding|outstanding_both|null.'),
    # class 3: "(same SO backlog / DO pending report as so_outstanding above, never a new tool)"
    Edit('replace', 'These two name WHICH document an outstanding ask means (same SO backlog / DO pending report as "so_outstanding" above, never a new tool).', 'These two name WHICH document an outstanding ask means:'),
    # class 3: "never ... - the OLD undelivered-order bucket" is commentary; the rule kept.
    Edit('replace', '  - "delivery order outstanding", "DO outstanding", "outstanding DO" when paired with the word "outstanding" (never a bare "outstanding DO" alone, which stays "outstanding" - the OLD undelivered-order bucket), "pending delivery order", "pending DO", "DO pending", "belum DO keluar" together with an explicit outstanding/pending word -> "do_outstanding"', '  - "delivery order outstanding", "DO outstanding", "outstanding DO" when paired with the word "outstanding" (a bare "outstanding DO" alone stays "outstanding"), "pending delivery order", "pending DO", "DO pending", "belum DO keluar" together with an explicit outstanding/pending word -> "do_outstanding"'),
    # class 1: "THE DOCUMENT WORD DECIDES THE SCOPE WHEREVER IT SITS ... in the middle of a ques
    Edit('replace', '  - A bare "outstanding", "o/s", "os", "backlog" with NO document word (no "sales order"/"SO"/"delivery order"/"DO"/"both") stays order_status "outstanding"; the CRM (never the parser) asks which document it means.\nTHE DOCUMENT WORD DECIDES THE SCOPE WHEREVER IT SITS IN THE MESSAGE - beside the product, after the customer\'s name, before a location, in the middle of a question.\n  - "Srtwc8518-SH dealer delivery order outstanding how many at <warehouse code>?" -> "do_outstanding", document ["DO"] (product SRTWC8518-SH, warehouse <warehouse code>) - NOT bare "outstanding"\n  - "SRTWT7443 sales order outstanding for <warehouse code>" -> "so_outstanding", document ["SO"] (product SRTWT7443, warehouse <warehouse code>)\n  - "how much SRTWT7445 outstanding both at <warehouse code>" -> "outstanding_both", document ["SO", "DO"]\n  - "what is outstanding for SRTWT7445 at <warehouse code>" -> bare "outstanding", document [] (no document word anywhere in it, so the CRM asks)', '  - A bare "outstanding", "o/s", "os", "backlog" with NO document word (no "sales order"/"SO"/"delivery order"/"DO"/"both") stays order_status "outstanding"; the CRM (never the parser) asks which document.\nThe document word decides wherever it sits (DOCUMENT):\n  - "Srtwc8518-SH dealer delivery order outstanding how many at <warehouse code>?" -> "do_outstanding", document ["DO"] (product SRTWC8518-SH, warehouse <warehouse code>) - NOT bare "outstanding"\n  - "SRTWT7443 sales order outstanding for <warehouse code>" -> "so_outstanding", document ["SO"] (product SRTWT7443, warehouse <warehouse code>)\n  - "how much SRTWT7445 outstanding both at <warehouse code>" -> "outstanding_both", document ["SO", "DO"]\n  - "what is outstanding for SRTWT7445 at <warehouse code>" -> bare "outstanding", document [] (no document word)'),
    # lever 4+5: the option-list examples grouped per option set ("-> [n]" = reference_positions
    Edit('replace', 'When the user block says the assistant is waiting for a reply AND lists "Open question options:", a numbered question is open. A message that ANSWERS it, by number ("2") or by words naming an option ("delivery order", "the DO list", "sales", "both", "all", "everything"), puts that option\'s number in reference_positions; every other field (domain_hint, intent_hint, order_status, domain_in_message, entities, message_type) is filled exactly as for the same words with no question open. A pick blanks nothing.\n  - options "1. SRTWC286-SH ... 4. SRTWC286-SH-NEW ..." + "4" -> reference_positions [4], domain_in_message false (no domain word)\n  - the same options + "4 stock" or "stock for the 4th" -> reference_positions [4], domain_hint "inventory", intent_hint "check_stock", domain_in_message true\n  - the same options + "check stock" (no number, no option named) -> domain_hint "inventory", intent_hint "check_stock", domain_in_message true, reference_positions []\n  - options "1. Sales orders, 2. Delivery orders, 3. Both" + "all" -> reference_positions [3]\n  - options "1. Sales order list, 2. Delivery order list" + "DO list" -> reference_positions [2]\nA PARAPHRASE is still an answer ("gimme the list plss", "show me", "yes list please", "the SO one", "let me see them"): pick the option meant; when only ONE option is offered, any request for "the list" is that option (options "1. Sales order list" + "gimme the list plss" -> reference_positions [1]).\n"ALL" WITH NO "ALL" OPTION IS EVERY NUMBER: asked for all of them when no option offers "both" / "all" / "everything", emit EVERY option\'s number (one answer, not a wider search): options "1. <customer name>, 2. <customer name>, 3. <customer name>, 4. <customer name>" + "All" -> reference_positions [1,2,3,4].\nA message that asks something NEW (a product code, a customer name, an order number, any other topic) is NOT an answer: a fresh business_query with its own entities and domain_hint, reference_positions EMPTY (options "1. Sales order list, 2. Delivery order list" + "delivery to <customer name>" -> entities [<customer name> as customer], reference_positions []).\nA CODE OR NAME FROM THE LIST IS ITS POSITION: an offered option typed back (its code, or its name as listed) puts that option\'s number in reference_positions AND the code or name in entities as usual; the domain fields follow the message\'s own words.\n  - options "1. A, 2. B" + "B" -> reference_positions [2], entities [B]\n  - options "1. SRTWC286-SH ... 4. SRTWC286-SH-NEW ..." + "stoick SRTWC286-SH-NEW" -> reference_positions [4], entities [SRTWC286-SH-NEW], domain_hint "inventory", domain_in_message true ("stoick" is "stock")', 'An open numbered question = the user block says the assistant is waiting for a reply AND lists "Open question options:". An ANSWER, by number ("2") or by words naming an option ("delivery order", "the DO list", "sales", "both", "all", "everything"), puts that option\'s number in reference_positions; every other field as for the same words with no question open (a pick blanks nothing).\n  - options "1. SRTWC286-SH ... 4. SRTWC286-SH-NEW ..." + "4" -> reference_positions [4], domain_in_message false; + "4 stock" or "stock for the 4th" -> [4], domain_hint "inventory", intent_hint "check_stock", domain_in_message true; + "check stock" (no number, no option named) -> those domain fields, reference_positions []\n  - options "1. Sales orders, 2. Delivery orders, 3. Both" + "all" -> [3]; options "1. Sales order list, 2. Delivery order list" + "DO list" -> [2]\nA PARAPHRASE answers too ("gimme the list plss", "the SO one"): pick the option meant; with only ONE option offered, any request for "the list" is it ("1. Sales order list" + "gimme the list plss" -> [1]).\n"ALL" WITH NO "ALL" OPTION IS EVERY NUMBER: all of them asked, no "both" / "all" / "everything" option -> EVERY option\'s number, one answer, not a wider search (four customer options + "All" -> [1,2,3,4]).\nA message asking something NEW (a product code, a customer name, an order number, another topic) is NOT an answer: a fresh business_query with its own entities and domain_hint, reference_positions [] ("1. Sales order list, 2. Delivery order list" + "delivery to <customer name>" -> entities [<customer name> as customer]).\nA CODE OR NAME FROM THE LIST IS ITS POSITION: an offered option typed back (its code or listed name) -> its number in reference_positions AND the code or name in entities, domain fields from the message\'s own words: "1. A, 2. B" + "B" -> [2], entities [B]; "1. SRTWC286-SH ... 4. SRTWC286-SH-NEW ..." + "stoick SRTWC286-SH-NEW" -> [4], entities [SRTWC286-SH-NEW], domain_hint "inventory", domain_in_message true ("stoick" is "stock").'),
    # lever 4: heading part ("== ... ==") verbatim, body after it terse; "("<customer name>" -> 
    Edit('replace', '== IN AN ORDER OR OUTSTANDING ASK, A SHORT TOKEN IS A LOCATION == Under domain_hint "order" (a DO / SO / outstanding question), a SHORT token that is not a product code and follows "for", "at", "in", or stands alone beside the product -> a WAREHOUSE entity, hint "warehouse", NEVER "customer". SHORT is only: (a) at most 4 characters, letters or letters with one digit; (b) a hyphenated site code of at most 10 characters; each as the Location candidates block spells a location.\n  - "SRTWT7443 sales order outstanding for <warehouse code>", "any DO for SRTWT7445 at <warehouse code>", "outstanding in <warehouse code>", "backlog <warehouse code>" -> each <warehouse code> is a warehouse entity (SRTWT7443 the product)\nAnything LONGER is a CUSTOMER name however it is capitalised ("<customer name>" -> a customer entity, never a warehouse). A product code carries digits ("SRTWC8517", "MSK11A-QT") and is neither.', '== IN AN ORDER OR OUTSTANDING ASK, A SHORT TOKEN IS A LOCATION == Under domain_hint "order" (DO / SO / outstanding), a SHORT non-product token after "for", "at", "in", or alone beside the product -> a "warehouse" entity, NEVER "customer". SHORT is only: (a) at most 4 characters, letters or letters with one digit; (b) a hyphenated site code of at most 10 characters; each as the Location candidates block spells a location.\n  - "SRTWT7443 sales order outstanding for <warehouse code>", "any DO for SRTWT7445 at <warehouse code>", "outstanding in <warehouse code>", "backlog <warehouse code>" -> each <warehouse code> a warehouse entity (SRTWT7443 the product)\nLONGER is a CUSTOMER name, however capitalised; a product code carries digits ("SRTWC8517", "MSK11A-QT") and is neither.'),
    # lever 4: one paragraph; "is purchase_order" folded (the first sentence maps "PO" / "purcha
    Edit('replace', 'What WE ordered from a SUPPLIER, never what a customer ordered from us: "PO", "PO placed", "purchase order", "PO for this item", "ordered from supplier", "supplier order", "采购单", "已下单" -> domain_hint "purchase_order", intent_hint "check_po" ("by supplier" / "by product" also sets group_by).\n"DO", "SO", "delivery order", "sales order" and a customer\'s name are NEVER purchase_order (they stay "order" / "check_order"). "PO" / "purchase order" ALONE, with or without a product, also inside a multi-domain ask ("stock, incoming and PO" -> domain_hint "inventory", the FIRST ask), is purchase_order, NEVER purchase_cost: only COST words ("cost", "last purchase cost", "how much did we pay") make purchase_cost.', 'What WE ordered from a SUPPLIER, never what a customer ordered from us: "PO", "PO placed", "purchase order", "PO for this item", "ordered from supplier", "supplier order", "采购单", "已下单" -> domain_hint "purchase_order", intent_hint "check_po" ("by supplier" / "by product" also sets group_by). "DO", "SO", "delivery order", "sales order" and a customer\'s name are NEVER purchase_order (they stay "order" / "check_order"). "PO" / "purchase order" ALONE, with or without a product, also in a multi-domain ask ("stock, incoming and PO" -> domain_hint "inventory", the FIRST ask), is NEVER purchase_cost: only COST words ("cost", "last purchase cost", "how much did we pay") make purchase_cost.'),
    # lever 4: terse.
    Edit('replace', 'Both cases are domain_hint "master_products", intent_hint "check_product". A PARTICULAR property named (steel grade, material, finish, width, length, height, wattage, capacity, colour, mounting, ...) always wins: requested_attributes = that property ("steel grade of SRTKT73SS" -> ["steel_grade"], "SRTKT73SS dimensions" -> the dimension keys). Else "spec" / "specs" / "specification" / "specifications" / "规格" as the only attribute word -> requested_attributes [], the WHOLE spec list ("SRTKT73SS spec", "spec for SRTKT73SS").', 'Both cases: domain_hint "master_products", intent_hint "check_product". A PARTICULAR property named (steel grade, material, finish, width, length, height, wattage, capacity, colour, mounting, ...) always wins: requested_attributes = it ("steel grade of SRTKT73SS" -> ["steel_grade"], "SRTKT73SS dimensions" -> the dimension keys); else "spec" / "specs" / "specification" / "specifications" / "规格" as the only attribute word -> requested_attributes [], the WHOLE spec list ("SRTKT73SS spec", "spec for SRTKT73SS").'),
    # lever 4: "and the SRTWC8517 above" dropped (the four examples show it).
    Edit('replace', 'In a PO or SPO / last-in ask ("PO for SRTWC8517", "PO SRTWC8517", "purchase order of SRTWC8517", "last in for SRTWC8517") the token after "for" / "of", or a bare code beside the PO word, is hint "product", NEVER "order", "order_number" or "customer_order"; only a PO / SO NUMBER shaped like "202602-S0002" (digits, a hyphen, then a letter) is an order entity. A product code starts with letters ("C-FH14", "MSK11A-QT", and the SRTWC8517 above).', 'In a PO or SPO / last-in ask ("PO for SRTWC8517", "PO SRTWC8517", "purchase order of SRTWC8517", "last in for SRTWC8517") the token after "for" / "of", or a bare code beside the PO word, is hint "product", NEVER "order", "order_number" or "customer_order"; only a PO / SO NUMBER shaped like "202602-S0002" (digits, a hyphen, a letter) is an order entity; a product code starts with letters ("C-FH14", "MSK11A-QT").'),
    # class 1 + lever 4: same rule, pointer to its home. Pass 2: the confirmation examples ("yes
    Edit('replace', 'When the previous reply offered to escalate and the current message ASKS SOMETHING (a product, stock, a PO, an SO, a last-in, with or without a code), it is a business_query with escalation.is_escalation_confirmation FALSE and the entity the customer named THIS turn; only a message that answers the offer ("yes", "yes escalate", "ok please escalate") is a confirmation.', "An ASK over an escalate offer (a product, stock, a PO, an SO, a last-in, with or without a code) is a business_query, is_escalation_confirmation FALSE, with this turn's entity (ESCALATION CONFIRMATION)."),
    # lever 4: terse.
    Edit('replace', '"delivery to <customer name>", "hantar ke <customer name>", "any DO for X" (a customer or product next to a delivery / order / DO word) -> business_query, intent_hint check_order, domain_hint order, that name as an entity with current_message true, is_escalation_confirmation false, even with an escalate offer open: request_for_help is ONLY a request for a HUMAN.', '"delivery to <customer name>", "hantar ke <customer name>", "any DO for X" (a customer or product beside a delivery / order / DO word) -> business_query, intent_hint check_order, domain_hint order, that name an entity with current_message true, is_escalation_confirmation false, even with an escalate offer open (request_for_help is ONLY for a HUMAN).'),
    # lever 4: terse.
    Edit('replace', 'For requested_attributes ONLY, never an entity\'s canonical_code: the customer\'s own attribute phrase WHOLE ("seat cover material", "list price"), never a shortened token; a base property (price, dimensions, description, name) counts too.', 'requested_attributes ONLY (never an entity\'s canonical_code): the customer\'s own attribute phrase WHOLE ("seat cover material", "list price"), never shortened; a base property (price, dimensions, description, name) counts too.'),
    # lever 4+5: one paragraph; the "last purchase cost for SRTWC8517" example dropped, the rule
    Edit('replace', 'What WE PAID a supplier, never what WE CHARGE: "last purchase cost", "last cost", "what did we pay", "what did we pay for", "buying price", "purchase price", "cost price", "上次采购价", "成本", "harga belian terakhir", "harga beli" -> intent_hint "check_po_cost", domain_hint "purchase_cost"; "last 3 purchase cost" also sets top_n = 3, "by warehouse" / "by location" group_by "warehouse".\nNEVER purchase_cost ("cost" alone is the everyday word for the SELLING price): "how much do we sell it for", "selling price", "what do we charge", "how much does it cost", "berapa harga", "多少钱" stay domain_hint "master_products", "promotion" or plain check_stock. "last purchase cost for SRTWC8517" names a PRODUCT, never an order.', 'What WE PAID a supplier, never what WE CHARGE: "last purchase cost", "last cost", "what did we pay", "what did we pay for", "buying price", "purchase price", "cost price", "上次采购价", "成本", "harga belian terakhir", "harga beli" -> intent_hint "check_po_cost", domain_hint "purchase_cost"; "last 3 purchase cost" also sets top_n = 3, "by warehouse" / "by location" group_by "warehouse". NEVER purchase_cost ("cost" alone is the everyday word for the SELLING price): "how much do we sell it for", "selling price", "what do we charge", "how much does it cost", "berapa harga", "多少钱" (they stay "master_products", "promotion" or plain check_stock). The code in it is a PRODUCT, never an order.'),
    # lever 4: "(English, Malay, Chinese, Manglish)" restates "any language or mix".
