def apply(text: str) -> str | None:
    """`text` with every edit applied in order, or None (reason logged) when the text has no line equal to the
    marker or any anchor is missing or found more than once at its turn."""
    if not any(ln.strip() == MARKER for ln in text.splitlines()):
        logger.info("prompt diet: the text carries no %s line", MARKER)
        return None
    for edit in EDITS:
        if edit.op == "replace_line":
            lines = text.split("\n")
            hits = [i for i, ln in enumerate(lines) if _sha(ln) == edit.anchor]
            found = len(hits)
            if found == 1:
                if edit.payload:
                    lines[hits[0]] = edit.payload
                else:
                    del lines[hits[0]]
                text = "\n".join(lines)
        else:
            found = text.count(edit.anchor)
            if found == 1:
                text = text.replace(edit.anchor, edit.payload, 1)
        if found != 1:
            logger.warning("prompt diet: anchor %r found %d times, nothing published", edit.anchor[:70], found)
            return None
    return text


def build(production_text: str) -> str | None:
    """The diet text for the production-labelled parser text (the list-free edits first when it does not
    carry the marker yet), or None when either step does not apply."""
    if any(ln.strip() == MARKER for ln in production_text.splitlines()):
        base: str | None = production_text
    else:
        base = chatbot_lookup_edits.apply(production_text)
    if base is None:
        return None
    return apply(base)
